const http = this.helpers.httpRequest;

// Buscar últimos 7 días para asegurar cobertura
const d = new Date();
d.setDate(d.getDate() - 7);
const since = d.toISOString().split('T')[0];

const KEYWORDS = [
  'eléctric','electric','energía','energia','iluminación','iluminacion',
  'subestación','subestacion','transformador','generador','paneles solares',
  'fotovoltaic','RETIE','montaje eléctrico','mantenimiento eléctrico',
  'obras civiles','construcción','construccion','adecuación','remodelación',
  'infraestructura','vías','vias','paviment','alcantarillado','edificio',
  'consultoría','consultoria','interventoría','interventoria',
  'diseño','diseno','ingeniería','ingenieria','arquitect','topograf',
  'suministro','dotación','dotacion','mobiliario','equipo',
  'software','sistemas','tecnología','tecnologia','desarrollo web',
  'mantenimiento','reparación','reparacion','adecuacion'
];

const url = `https://www.datos.gov.co/resource/jbjy-vk9h.json?$select=nombre_entidad,descripcion_del_proceso,valor_del_contrato,fecha_de_firma,departamento,ciudad,modalidad_de_contratacion,tipo_de_contrato,urlproceso,id_contrato&$where=fecha_de_firma%20%3E=%20'${since}'&$order=fecha_de_firma%20DESC&$limit=30`;

const data = await http({ method:'GET', url });
if (!Array.isArray(data)) return { error: 'No data', url };

let sent = 0;
const matches = [];

for (const item of data) {
  const desc = (item.descripcion_del_proceso || '').toLowerCase();
  const entidad = (item.nombre_entidad || '').toLowerCase();
  const tipo = (item.tipo_de_contrato || '').toLowerCase();
  const searchText = desc + ' ' + entidad + ' ' + tipo;
  const matched = KEYWORDS.filter(kw => searchText.includes(kw.toLowerCase()));

  if (matched.length > 0 && sent < 5) {
    const valor = parseInt(item.valor_del_contrato) || 0;
    const valorFmt = new Intl.NumberFormat('es-CO', { style:'currency', currency:'COP', minimumFractionDigits:0 }).format(valor);
    const fecha = (item.fecha_de_firma || '').split('T')[0];
    const text = `📋 *Licitación SECOP*\n\n🏛️ *${item.nombre_entidad}*\n📍 ${item.departamento || ''}, ${item.ciudad || ''}\n📝 ${(desc || '').substring(0,120)}...\n💰 ${valorFmt}\n📅 ${fecha}\n🏷️ ${item.modalidad_de_contratacion}\n🔑 ${matched.slice(0,3).join(', ')}\n\n🔗 ${item.urlproceso?.url || 'https://community.secop.gov.co/'}\n\n⚡ SECOP Alertas`;

    try {
      await http({
        method:'POST',
        url:'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
        headers:{ 'apikey':'wasapea-evo-key-2026', 'Content-Type':'application/json' },
        body:{ number:'573106055920', text }
      });
      matches.push({ entidad: item.nombre_entidad, keywords: matched.slice(0,3), valor: valorFmt });
      sent++;
    } catch(e) {
      // skip send errors
    }
  }
}

return { sent, total: data.length, since, matches };
